begin;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('ba24c000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer,org integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'role','authenticated','org_id',pg_temp.id(org))::text,true)::void$$;
insert into auth.users(id,email) select pg_temp.id(n),'evaluation-population-'||n||'@test.local' from generate_series(10,16) n;
insert into public.organizations(id,slug,name) values(pg_temp.id(1),'evaluation-population-a','Population A'),(pg_temp.id(2),'evaluation-population-b','Population B');
insert into public.memberships(organization_id,user_id,role) values
 (pg_temp.id(1),pg_temp.id(10),'owner'),(pg_temp.id(1),pg_temp.id(11),'viewer'),(pg_temp.id(1),pg_temp.id(12),'branch_user'),
 (pg_temp.id(2),pg_temp.id(13),'owner'),(pg_temp.id(1),pg_temp.id(14),'planner'),(pg_temp.id(1),pg_temp.id(15),'approver'),(pg_temp.id(1),pg_temp.id(16),'admin');
insert into public.locations(id,organization_id,code,name_en,location_type,country_code,timezone)
 select pg_temp.id(20+n),pg_temp.id(case when n=2 then 2 else 1 end),'L'||n,'Location','branch','SA','Asia/Riyadh' from generate_series(0,2) n;
insert into public.items(id,organization_id,code,name_en,product_group,unit_of_measure,unit_cost,currency)
 values(pg_temp.id(30),pg_temp.id(1),'P1','Part','Test','EA',1,'SAR');
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(21));
create temporary table fixture(population jsonb,dataset uuid,input jsonb,report jsonb,saved uuid,evaluation uuid);
insert into fixture(population) values('{"item_code":"P1","location_code":"L0","dataset_name":"Equipment population","unit":"EA","source":"Synthetic evidence","as_of":"2026-01-02","available_on":"2026-01-03","confirmed":true,"non_overlapping":true,"rows":[{"group_code":"A","group_name":"Known","installed_on":"2026-01-01","active_assets":"12","parts_per_asset":"2.5"},{"group_code":"B","group_name":"Unknown","installed_on":null,"active_assets":"3","parts_per_asset":"0.001"},{"group_code":"C","group_name":"Zero","installed_on":null,"active_assets":"0","parts_per_asset":"1"}]}');
grant all on fixture to authenticated;
select pg_temp.login(10,1); set local role authenticated;
update fixture set dataset=public.installed_base_save(pg_temp.id(1),population,pg_temp.id(39),public.installed_base_preview(pg_temp.id(1),population)->>'fingerprint');
update fixture set input=jsonb_build_object('dataset_id',dataset,'scenario_name','Replacement demand','cutoff','2026-01-03','horizon_days',3,'confirmed',true,'rates','[{"group_code":"A","daily_rate":"0.01","source":"Explicit rate A","available_on":"2026-01-03"},{"group_code":"B","daily_rate":"0.000000001","source":"Explicit rate B","available_on":"2026-01-02"},{"group_code":"C","daily_rate":"0","source":"Explicit zero","available_on":"2026-01-01"}]'::jsonb);

update fixture set report=public.installed_base_demand_preview(pg_temp.id(1),input);
update fixture set saved=public.installed_base_demand_save(pg_temp.id(1),input,pg_temp.id(40),report->>'fingerprint');
update fixture set input=jsonb_build_object('scenario_id',saved,'evaluation_name','Retrospective sales','confirmed',true);
reset role;
insert into public.demand_history(organization_id,item_id,location_id,demand_date,quantity,lost_sales_quantity,unit_of_measure) values
 (pg_temp.id(1),pg_temp.id(30),pg_temp.id(20),'2026-01-04',1,0,'EA'),
 (pg_temp.id(1),pg_temp.id(30),pg_temp.id(20),'2026-01-06',0,2,'EA');
set local role authenticated;
create function pg_temp.preview(overrides jsonb default '{}') returns jsonb language sql as $$select public.installed_base_evaluation_preview(pg_temp.id(1),input||overrides) from fixture$$;
create function pg_temp.save(n integer default 50,overrides jsonb default '{}',fingerprint text default null) returns uuid language sql as $$select public.installed_base_evaluation_save(pg_temp.id(1),input||overrides,pg_temp.id(n),coalesce(fingerprint,report->>'fingerprint')) from fixture$$;
update fixture set report=pg_temp.preview();
select is((select report#>>'{totals,expected}' from fixture),'0.900000000009','exact expected total');
select is((select report#>>'{totals,sold}' from fixture),'1','sold scored separately');
select is((select report#>>'{totals,lost_sales}' from fixture),'2','lost sales preserved separately');
select is((select report#>>'{totals,difference}' from fixture),'-0.099999999991','expected minus sold convention');
select is((select report#>>'{totals,absolute_error}' from fixture),'1.300000000003','exact absolute sum');
select is((select (report#>>'{totals,squared_error}')::numeric from fixture),0.669999999999400000000027::numeric,'exact squared sum');
select is((select report->>'recorded_days' from fixture),'2','lost-only row is recorded evidence');
select is((select report->>'zero_filled_days' from fixture),'1','only absent day is filled');
select is((select report#>'{days,1,recorded}' from fixture),'false'::jsonb,'missing day distinguished');
select is((select report#>'{days,1,supplied_unit}' from fixture),'null'::jsonb,'no fabricated supplied unit');
select is((select report#>>'{days,0,difference}' from fixture),'-0.699999999997','exact daily difference');
select is((select report#>'{source,scenario}' from fixture),(select report from public.installed_base_demand_scenarios where id=(select saved from fixture)),'entire source scenario copied');
select throws_ok($$select pg_temp.preview('{"confirmed":false}')$$,'MQ422','invalid evaluation input or unconfirmed complete history','missing dates require confirmation before preview');
select throws_ok($$select pg_temp.preview('{"evaluation_name":" "}')$$,'MQ422','invalid evaluation input or unconfirmed complete history','blank name rejected');
select throws_ok($$select pg_temp.preview('{"scenario_id":"bad"}')$$,'MQ422','invalid evaluation input or unconfirmed complete history','invalid source ID rejected');
select throws_ok($$select pg_temp.preview(jsonb_build_object('evaluation_name',repeat('x',5000)))$$,'MQ422','invalid evaluation input or unconfirmed complete history','bounded payload');
update fixture set evaluation=pg_temp.save();
select is(pg_temp.save(),(select evaluation from fixture),'identical retry stable');
select is(pg_temp.save(50,'{"evaluation_name":" Retrospective sales "}'),(select evaluation from fixture),'trimmed retry canonical');
select throws_ok($$select pg_temp.save(50,'{"evaluation_name":"Other"}')$$,'MQ409','evaluation request conflicts','conflicting retry rejected');
select throws_ok($$select pg_temp.save(51,'{}',repeat('a',64))$$,'MQ409','evaluation evidence changed; refresh preview','stale fingerprint rejected');
select throws_ok($$update public.installed_base_evaluations set evaluation_name='Changed'$$,'42501',null,'table immutable to members');
select throws_ok($$select app.installed_base_evaluation_input('{}')$$,'42501',null,'normalizer is private');
reset role;
update public.demand_history set quantity=2 where organization_id=pg_temp.id(1) and demand_date='2026-01-04';
set local role authenticated;
select throws_ok($$select pg_temp.save(51)$$,'MQ409','evaluation evidence changed; refresh preview','changed sales require preview refresh');
select is(pg_temp.save(),(select evaluation from fixture),'retry preserves historical sales');
select is((select report#>>'{totals,sold}' from public.installed_base_evaluations),'1','saved result not rewritten');
reset role;
update public.demand_history set unit_of_measure=null where organization_id=pg_temp.id(1) and demand_date='2026-01-06';
set local role authenticated;
select throws_ok($$select pg_temp.preview()$$,'MQ422','sales units missing or incompatible','even lost-only units must be known');
reset role;
update public.demand_history set unit_of_measure='KG' where organization_id=pg_temp.id(1) and demand_date='2026-01-06';
set local role authenticated;
select throws_ok($$select pg_temp.preview()$$,'MQ422','sales units missing or incompatible','mixed units rejected');
select pg_temp.login(11,1);
select is((select count(*)::int from public.installed_base_evaluations),1,'viewer can inspect');
select throws_ok($$select pg_temp.save()$$,'MQ403','evaluation save forbidden','viewer cannot retry');
select pg_temp.login(15,1);
select throws_ok($$select pg_temp.save()$$,'MQ403','evaluation save forbidden','approver cannot save');
select pg_temp.login(12,1);
select is((select count(*)::int from public.installed_base_evaluations),0,'branch hides other location');
select throws_ok($$select pg_temp.preview()$$,'MQ404','demand scenario unavailable','branch cannot preview hidden source');
select pg_temp.login(13,2);
select is((select count(*)::int from public.installed_base_evaluations),0,'cross tenant hidden');
select throws_ok($$select pg_temp.preview()$$,'MQ404','demand scenario unavailable','cross tenant source hidden');
reset role;
insert into public.membership_locations values(pg_temp.id(1),pg_temp.id(12),pg_temp.id(20));
select pg_temp.login(12,1); set local role authenticated;
select is((select count(*)::int from public.installed_base_evaluations),1,'permitted branch can inspect');
reset role;
select is((select count(*)::int from public.audit_log where organization_id=pg_temp.id(1) and table_name='installed_base_evaluations'),1,'retries create one audit record');
-- Delete only this transaction's synthetic sources; the captured evaluation survives.
delete from public.demand_history where organization_id=pg_temp.id(1);
delete from public.installed_base_demand_scenarios where organization_id=pg_temp.id(1);
delete from public.installed_base_datasets where organization_id=pg_temp.id(1);
delete from public.items where organization_id=pg_temp.id(1);
select pg_temp.login(10,1); set local role authenticated;
select is(pg_temp.save(),(select evaluation from fixture),'retry after source deletion retains files');
select throws_ok($$select pg_temp.save(55)$$,'MQ404','demand scenario unavailable','new save requires visible source');
select is((select report#>>'{totals,sold}' from public.installed_base_evaluations),'1','copied sales retained after deletion');
reset role;
delete from public.locations where id=pg_temp.id(20);
select is((select count(*)::int from public.installed_base_evaluations),0,'location cascade retained');
select * from finish(); rollback;
